WITH valid_inventory AS (SELECT *, DAY(last_restock) AS last_restock_day FROM inventory WHERE product_id IN (4, 5, 8, 9) AND last_restock BETWEEN '2023-06-01' AND '2023-08-05'), summary AS (SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, MAX(quantity) AS max_quantity FROM valid_inventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT last_restock_cohort, max_quantity FROM summary ORDER BY last_restock_cohort ASC, max_quantity DESC
